const marketModel={player:0,position:'all',club:'all',age:45,history:[]};
try{marketModel.history=JSON.parse(localStorage.getItem('lockerdata.valuations.v2')||'[]').filter(r=>typeof r.name==='string'&&typeof r.time==='string'&&Number.isFinite(r.eur)&&Number.isFinite(r.vnd)).slice(-20);}catch{/* Optional local history is unavailable. */}
const marketInput={rating:7,output:6,age:28,months:24,base:100000,fx:26500,demand:1,status:1,national:1,tier:1};
function marketApplyInputs(){const next={...marketInput};document.querySelectorAll('[data-market-input]').forEach(el=>{if(el.value==='')throw Error('Điền đầy đủ các tham số trước khi tính.');next[el.dataset.marketInput]=Number(el.value);});LockerEngine.valuation(next);Object.assign(marketInput,next);}
function marketMoney(n,currency){return new Intl.NumberFormat('vi-VN',{style:'currency',currency,maximumFractionDigits:0}).format(n);}
function marketPreset(p){return {...marketInput,rating:rate(p),age:p.age,output:Math.min(10,(p.goals+p.assists)*90/p.minutes*10),base:p.pos==='GK'?80000:['CB','LB','RB'].includes(p.pos)?90000:100000};}
function marketModelPage(){const p=players.find(p=>p.id===marketModel.player)||players[0],v=LockerEngine.valuation(marketInput),rank=players.filter(p=>(marketModel.position==='all'||p.pos===marketModel.position)&&(marketModel.club==='all'||p.team===+marketModel.club)&&p.age<=marketModel.age).map(p=>({p,v:LockerEngine.valuation(marketPreset(p))})).sort((a,b)=>b.v.eur-a.v.eur),clubSums=new Map();rank.forEach(({p,v})=>clubSums.set(p.team,(clubSums.get(p.team)||0)+v.eur));const fields=[['rating','Điểm 6 tháng (giả định)',0,10,.01],['output','Chỉ số đóng góp 0–10',0,10,.01],['age','Tuổi',16,45,1],['months','Hợp đồng còn lại (tháng)',0,60,1],['base','Giá nền theo vai trò (EUR)',1000,1000000,1000],['fx','Tỷ giá kịch bản VNĐ/EUR',10000,100000,100],['national','Hệ số tuyển quốc gia',1,1.5,.05],['tier','Hệ số giải đấu',.5,2,.05],['demand','Nhu cầu nội địa',.1,4,.1],['status','Hệ số danh tiếng',.1,3,.1]];return heading('Định giá & kịch bản thị trường','EUR → VNĐ · Công thức và giả định có thể kiểm tra','<span class="sample-tag">Mô hình thử nghiệm</span>')+`<div class="studio-grid"><section class="panel studio-card"><label>Cầu thủ trong bộ mẫu<select id="market-person">${players.map(x=>`<option value="${x.id}" ${x.id===p.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><p>Thông tin tuổi, CLB và hiệu suất trong bộ này là minh họa. Đổi cầu thủ sẽ nạp lại giá nền và chỉ số đóng góp mẫu.</p><div class="studio-form">${fields.map(([key,label,min,max,step])=>`<label>${label}<input data-market-input="${key}" type="number" min="${min}" max="${max}" step="${step}" value="${marketInput[key]}"></label>`).join('')}</div><button class="button primary" data-market-apply="true">Tính lại kịch bản</button><button class="button" data-market-save="true">Lưu kịch bản trên máy</button><p>Bấm Tính lại sau khi chỉnh tham số. Lưu kịch bản cũng áp dụng toàn bộ giá trị đang nhập.</p></section><section class="panel studio-card"><h2>${esc(p.name)}</h2><div class="studio-value-output"><span>GIÁ TRỊ MÔ HÌNH EUR</span><strong>${marketMoney(v.eur,'EUR')}</strong><span>LÓT TAY MÔ PHỎNG · TỔNG</span><strong>${marketMoney(v.vnd,'VND')}</strong><p>Tỷ giá do bạn đặt: ${fmt(marketInput.fx)} VNĐ/EUR. Không phải tỷ giá trực tiếp hay mức phí đã giao dịch.</p></div><h3>LD-value-2.0</h3><p>Giá nền × (điểm × 0.35 + đóng góp × 0.25) × tuổi × tuyển quốc gia × hợp đồng × giải đấu.</p><p>Hệ số hiện tại: hiệu suất ${v.factors.performance.toFixed(3)} · tuổi ${v.factors.age} · hợp đồng ${v.factors.contract} · tuyển ${v.factors.national} · giải ${v.factors.tier}.</p><p>VNĐ = EUR chưa làm tròn × tỷ giá × nhu cầu × danh tiếng. EUR làm tròn 1.000; VNĐ làm tròn 1 triệu.</p><details><summary>Hệ số tuổi & hợp đồng</summary><p>Tuổi: dưới 22 ×1.3; 22–24 ×1.15; 25–28 ×1; 29–31 ×0.85; trên 31 ×0.75. Hợp đồng: hết hạn ×0.6; ≤6 tháng ×0.75; ≤12 ×0.9; ≤24 ×1; còn lại ×1.1. Các mốc bổ sung là lựa chọn thiết kế, chưa hiệu chỉnh thị trường.</p></details><p>Không phải định giá Transfermarkt, phí chuyển nhượng xác nhận hay khoảng tin cậy. Hợp đồng ở đây là giả định nhập tay.</p></section></div><section class="panel studio-card"><h2>Xếp hạng · ${rank.length}/${players.length} hồ sơ mẫu</h2><div class="studio-form"><label>Vị trí<select id="market-position"><option value="all">Tất cả</option>${[...new Set(players.map(p=>p.pos))].map(pos=>`<option ${marketModel.position===pos?'selected':''}>${pos}</option>`).join('')}</select></label><label>CLB<select id="market-club"><option value="all">Tất cả</option>${teams.map((t,i)=>`<option value="${i}" ${marketModel.club===String(i)?'selected':''}>${esc(t[0])}</option>`).join('')}</select></label><label>Tuổi tối đa<input id="market-age" type="number" min="16" max="45" value="${marketModel.age}"></label></div><p>Xếp hạng dùng hệ số hợp đồng/tỷ giá/nhu cầu chung ở form, tuổi và hiệu suất mẫu riêng mỗi người. Chỉ số đóng góp mẫu = (bàn + kiến tạo)/90 phút × 10, chặn 0–10; chưa phù hợp đánh giá thủ môn hoặc hậu vệ. Không có phân loại ngoại binh/quốc tịch đã xác minh.</p><div class="table-wrap"><table><thead><tr><th>#</th><th>Cầu thủ</th><th>CLB mẫu</th><th>Tuổi</th><th>Vị trí</th><th>EUR</th><th>VNĐ</th></tr></thead><tbody>${rank.map(({p,v},i)=>`<tr><td>${i+1}</td><td>${esc(p.name)}</td><td>${esc(teams[p.team][0])}</td><td>${p.age}</td><td>${p.pos}</td><td>${marketMoney(v.eur,'EUR')}</td><td>${marketMoney(v.vnd,'VND')}</td></tr>`).join('')||'<tr><td colspan="7">Không có hồ sơ phù hợp.</td></tr>'}</tbody></table></div><h3>Tổng giá trị hồ sơ đang lọc theo CLB</h3><p>${[...clubSums].map(([id,total])=>`${esc(teams[id][0])}: ${marketMoney(total,'EUR')}`).join(' · ')||'Chưa có hồ sơ.'}</p><p>Tổng của những hồ sơ hiện có, chưa phải giá trị toàn đội.</p></section><section class="panel studio-card"><h2>Lịch sử kịch bản cục bộ (${marketModel.history.length}/20)</h2><div class="table-wrap"><table><thead><tr><th>Thời gian</th><th>Cầu thủ</th><th>EUR</th><th>VNĐ</th></tr></thead><tbody>${marketModel.history.slice().reverse().map(r=>`<tr><td>${esc(r.time)}</td><td>${esc(r.name)}</td><td>${marketMoney(r.eur,'EUR')}</td><td>${marketMoney(r.vnd,'VND')}</td></tr>`).join('')||'<tr><td colspan="4">Chưa lưu kịch bản.</td></tr>'}</tbody></table></div><p>Đây là lịch sử giả định bạn lưu, không phải biến động giá trên thị trường.</p></section>`;}
pageViews.valuation=marketModelPage;
document.addEventListener('change',e=>{try{if(e.target.dataset.marketInput){const next={...marketInput,[e.target.dataset.marketInput]:Number(e.target.value)};LockerEngine.valuation(next);Object.assign(marketInput,next);render();}if(e.target.id==='market-person'){marketModel.player=+e.target.value;Object.assign(marketInput,marketPreset(players[marketModel.player]));render();}if(e.target.id==='market-position'){marketModel.position=e.target.value;render();}if(e.target.id==='market-club'){marketModel.club=e.target.value;render();}if(e.target.id==='market-age'){marketModel.age=Math.max(16,Math.min(45,Number(e.target.value)||45));render();}}catch(err){toast(err.message);render();}});
document.addEventListener('click',e=>{if(e.target.closest('[data-market-apply]')){try{marketApplyInputs();render();toast('Đã tính lại kịch bản.');}catch(err){toast(err.message);}return;}if(!e.target.closest('[data-market-save]'))return;try{marketApplyInputs();const value=LockerEngine.valuation(marketInput),record={name:players[marketModel.player].name,time:new Date().toISOString(),...value,input:{...marketInput}};const next=[...marketModel.history,record].slice(-20);localStorage.setItem('lockerdata.valuations.v2',JSON.stringify(next));marketModel.history=next;render();toast('Đã lưu kịch bản cục bộ.');}catch{toast('Không lưu được lịch sử trong trình duyệt này.');}});
render();
